package util;import java.lang.reflect.*;import java.util.*;import model.annotation.*;public class AnnotationValidator{public static String[] validate(Object o){List<String>e=new ArrayList<>();for(Field f:o.getClass().getDeclaredFields()){try{f.setAccessible(true);Object v=f.get(o);if(f.isAnnotationPresent(Positive.class)&&v instanceof Number n&&n.longValue()<=0)e.add(f.getName()+": "+f.getAnnotation(Positive.class).message());if(f.isAnnotationPresent(MaxLength.class)&&v instanceof String s&&s.length()>f.getAnnotation(MaxLength.class).value())e.add(f.getName()+": max length "+f.getAnnotation(MaxLength.class).value());}catch(ReflectiveOperationException ex){e.add(ex.getMessage());}}return e.toArray(String[]::new);}}
